class Solution {
public:
    Node* findRoot(vector<Node*> tree) {
        long long net = 0;
        for (Node* node : tree) {
            net += node->val;
            for (Node* child : node->children) {
                net -= child->val;
            }
        }
        for (Node* node : tree) {
            if (node->val == net) return node;
        }
        return nullptr;
    }
};

class Solution {
    public Node findRoot(List<Node> tree) {
        long net = 0;
        for (Node node : tree) {
            net += node.val;
            for (Node child : node.children) {
                net -= child.val;
            }
        }
        for (Node node : tree) {
            if (node.val == net) return node;
        }
        return null;
    }
}

var findRoot = function(tree) {
    let net = 0;
    for (const node of tree) {
        net += node.val;
        for (const child of node.children) {
            net -= child.val;
        }
    }
    for (const node of tree) {
        if (node.val === net) return node;
    }
    return null;
};
